query:
-- Vérifier les notes orphelines
SELECT COUNT(*) as orphan_notes FROM notes WHERE residentId NOT IN (SELECT id FROM residents);

-- Vérifier les emailLogs orphelins
SELECT COUNT(*) as orphan_emailLogs FROM emailLogs WHERE residentId NOT IN (SELECT id FROM residents);

-- Supprimer les notes orphelines
DELETE FROM notes WHERE residentId NOT IN (SELECT id FROM residents);

-- Supprimer les emailLogs orphelins
DELETE FROM emailLogs WHERE residentId NOT IN (SELECT id FROM residents);

-- Supprimer les emailLogs avec packageId orphelin
DELETE FROM emailLogs WHERE packageId IS NOT NULL AND packageId NOT IN (SELECT id FROM packages);

